script:
let sigs = [
  ["/system/xbin/su", "su Binary (xbin)", "HIGH", "Checks for su in /system/xbin"],
  ["/system/bin/su", "su Binary (bin)", "HIGH", "Checks for su in /system/bin"],
  ["/sbin/su", "su Binary (sbin)", "HIGH", "Checks for su in /sbin"],
  ["/system/sd/xbin/su", "su Binary (sd xbin)", "HIGH", "Checks for su in /system/sd/xbin"],
  ["/data/local/xbin/su", "su Binary (data xbin)", "HIGH", "Checks for su in /data/local/xbin"],
  ["busybox", "BusyBox Probe", "MEDIUM", "BusyBox reference — present on most rooted devices"],
  ["magisk", "Magisk Marker", "HIGH", "Magisk root reference (denylist/hidden enums may evade this)"],
  ["superuser", "Superuser Marker", "HIGH", "Superuser app reference"],
  ["supersu", "SuperSU Marker", "HIGH", "SuperSU app reference"],
  ["daemonsu", "SuperSU Daemon", "HIGH", "daemonsu — SuperSU daemon binary reference"],
  ["/system/app/Superuser", "Superuser APK Path", "HIGH", "Checks for the Superuser APK"],
  ["which su", "su PATH Probe", "MEDIUM", "Executes/shells 'which su' to detect root"]
];
for sig in sigs {
  let hits = find_strings(sig[0]);
  for h in hits {
    report(sig[1], h.address, sig[2], h.value + " (" + sig[3] + ")");
  }
}
